create extension if not exists "pgcrypto";
create table if not exists public.v6_workspaces (id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, created_at timestamptz not null default now());
create table if not exists public.v6_weekly_resets (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, reset_key text not null, created_at timestamptz not null default now(), unique(workspace_id, reset_key));
create table if not exists public.v6_members (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, nickname text not null, created_at timestamptz not null default now(), unique(workspace_id, nickname));
create table if not exists public.v6_characters (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, member_id uuid not null references public.v6_members(id) on delete cascade, name text not null, server text, class_name text, item_level numeric default 0, combat_power numeric default 0, memo text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(workspace_id, name));
create table if not exists public.v6_raids (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, name text not null, short_name text, min_level numeric not null default 0, max_level numeric not null default 9999, party_size int not null default 8, sort_order int not null default 999, created_at timestamptz not null default now());
create table if not exists public.v6_raid_parties (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, raid_id uuid not null references public.v6_raids(id) on delete cascade, party_no int not null, created_at timestamptz not null default now(), unique(raid_id, party_no));
create table if not exists public.v6_raid_placements (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, party_id uuid not null references public.v6_raid_parties(id) on delete cascade, character_id uuid not null references public.v6_characters(id) on delete cascade, slot_no int not null, created_at timestamptz not null default now(), unique(party_id, slot_no), unique(party_id, character_id));
create table if not exists public.v6_raid_clears (id uuid primary key default gen_random_uuid(), workspace_id uuid not null references public.v6_workspaces(id) on delete cascade, raid_id uuid not null references public.v6_raids(id) on delete cascade, party_id uuid not null references public.v6_raid_parties(id) on delete cascade, is_clear boolean not null default false, updated_at timestamptz not null default now(), unique(party_id));
alter table public.v6_workspaces enable row level security; alter table public.v6_weekly_resets enable row level security; alter table public.v6_members enable row level security; alter table public.v6_characters enable row level security; alter table public.v6_raids enable row level security; alter table public.v6_raid_parties enable row level security; alter table public.v6_raid_placements enable row level security; alter table public.v6_raid_clears enable row level security;
drop policy if exists "v6 all workspaces" on public.v6_workspaces; drop policy if exists "v6 all weekly_resets" on public.v6_weekly_resets; drop policy if exists "v6 all members" on public.v6_members; drop policy if exists "v6 all characters" on public.v6_characters; drop policy if exists "v6 all raids" on public.v6_raids; drop policy if exists "v6 all parties" on public.v6_raid_parties; drop policy if exists "v6 all placements" on public.v6_raid_placements; drop policy if exists "v6 all clears" on public.v6_raid_clears;
create policy "v6 all workspaces" on public.v6_workspaces for all using (true) with check (true); create policy "v6 all weekly_resets" on public.v6_weekly_resets for all using (true) with check (true); create policy "v6 all members" on public.v6_members for all using (true) with check (true); create policy "v6 all characters" on public.v6_characters for all using (true) with check (true); create policy "v6 all raids" on public.v6_raids for all using (true) with check (true); create policy "v6 all parties" on public.v6_raid_parties for all using (true) with check (true); create policy "v6 all placements" on public.v6_raid_placements for all using (true) with check (true); create policy "v6 all clears" on public.v6_raid_clears for all using (true) with check (true);
do $$ begin begin alter publication supabase_realtime add table public.v6_characters; exception when duplicate_object then null; end; begin alter publication supabase_realtime add table public.v6_raids; exception when duplicate_object then null; end; begin alter publication supabase_realtime add table public.v6_raid_parties; exception when duplicate_object then null; end; begin alter publication supabase_realtime add table public.v6_raid_placements; exception when duplicate_object then null; end; begin alter publication supabase_realtime add table public.v6_raid_clears; exception when duplicate_object then null; end; end $$;
